import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易義海撮要卷十","description":"周易義海撮要 - 周易義海撮要卷十","frontmatter":{"title":"周易義海撮要卷十","description":"周易義海撮要 - 周易義海撮要卷十"},"headers":[],"relativePath":"classics/yihai-cuoyao/011.md","filePath":"classics/yihai-cuoyao/011.md"}'),i={name:"classics/yihai-cuoyao/011.md"};function o(c,a,r,_,n,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="周易義海撮要卷十" tabindex="-1">周易義海撮要卷十 <a class="header-anchor" href="#周易義海撮要卷十" aria-label="Permalink to “周易義海撮要卷十”">​</a></h1><p>欽定四庫全書</p><p>宗李衡撰。</p><p>有天地，然後萬物生焉。盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。物稚不可不養也，故受之以需。需者，飲食之道也。飲食必有訟，故受之以訟。訟必有眾起，故受之以師，師者，眾也。眾必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。物畜然後有禮，故受之以履。</p><p>屯則塞，塞則盈，此以雲雷言也。需非飲食也，飲食之道也。萬物之於天，則以雨為需。人之於君，則以飲食為需。兩相比者，情也，而義不足以畜，則情勝義而不可久，故比必有所畜，而所以止之也。物畜則萬物盛多，而禮所由興也。 龔</p><p>履而泰然後安，故受之以泰。泰者，通也。物不可以終通，故受之以否。物不可以終否，故受之以同人。與人同者，物必歸焉，故受之以大有。有大者不可以盈，故受之以謙。有大而能謙必豫，故受之以豫。豫必有隨，故受之以隨。以喜隨人者必有事，故受之以蠱。蠱者，事也。有事而後可大，故受之以臨。臨者，大也。物大然後可觀，故受之以觀。</p><p>否則思通，人人同志，故可出門同人，不謀而合。順以動者，眾之所隨。可大之業，由事而生。 注：能行禮者，其身必安，故以「泰」次履。大有天下之眾，又能謙順，則人必悅豫而隨之，故以「豫」次「謙」。以喜隨人，久而已極，必敗成事，故「蠱」次「隨」。事既久敗，必須有才德之人以臨治之，故以「臨」次蠱。臨人之道，必在中正，中正必有可觀，故「觀」次「臨」。 胡：「以喜隨人」者，溺於燕安，故至於蠱，蠱則有事。 坡：以喜隨人者必有事，此無思無慮之聖人所以迫而後動，不得已而後起也。豫所謂喜也。 龔：聖人順動能謙，為物所說，所以為豫。人既說豫，自然隨之，則謙順在君，說豫在人。 孔：</p><p>可觀而後有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而已，故受之以賁。賁者，飾也。致飾然後亨則盡矣，故受之以剝。剝者，剝也。物不可以終盡，剝窮上反下，故受之以復。復則不妄矣，故受之以無妄。無妄然後可畜，故受之以大畜。物畜然後可養，故受之以頤。頤者，養也。不養則不可動，故受之以大過。物不可以終過，故受之以坎。坎者，陷也。陷必有所麗，故受之以離。離者，麗也。可觀則萬方合會，相合則須飾以修外，極飾則實喪，不養則不可動，養過則厚，過而不已則陷沒。物窮則變，極陷則反所麗也。 注：君臣、父子、夫婦、朋友之際，所謂合也。直情而行之謂之苟，禮以飾情謂之賁。苟則易合，易合則相瀆，瀆則易離。賁則難合，難合則相敬，敬則久成。飾極則不勝而實衰，故剝 坡 可觀而後有所合，猶曰「不成章不達」也。賁者，飾也。詩、書之光，禮樂之容，車服文章，莫非賁也。致飾然後亨則盡矣，其周公、成王之時乎？禮儀三百，威儀三千，不可加也，有剝而已，譬之「日中則昃」也。故詩序假樂之後有戒焉。陽上而陰下，理之正也。自姤而上，則失正矣，故剝窮上反下而後復，復則陰陽各得其正而不妄，若老子所謂「歸根曰靜，靜曰覆命，覆命曰常」之時也。無妄者，天之命也，萬物聽焉。故有無妄然後可畜。在人君則取人以身之謂也。不養則不可動，雖形體亦然，況欲有為乎？故上九由頤，然後「利涉大川」也。小者之過，過其分而已，未及陷也。大者而過，則為已極矣，故過則陷。陷必有所麗，不必物也，雖性亦如之。唯能解脫者，無所麗也。 龔</p><p>有天地，然後有萬物，有萬物，然後有男女，有男女，然後有夫婦，有夫婦，然後有父子，有父子，然後有君臣，有君臣，然後有上下，有上下，然後禮義有所錯。夫婦之道，不可以不久也，故受之以恆。恆者，久也。物不可以久居其所，故受之以遁。遁者，退也。物不可以終遁，故受之以大壯。物不可以終壯，故受之以晉。晉者，進也。進必有所傷，故受之以明夷。夷者，傷也。傷於外者必反於家，故受之以家人。家道窮必乖，故受之以睽。睽者，乖也。乖必有難，故受之以蹇。蹇者，難也。物不可以終難，故受之以解。解者，緩也。緩必有所失，故受之以損。損而不已必益，故受之以益。</p><p>物之所居，不可以恆，宜與時升降。遁：君子以遠小人。遁而後亨，何可終邪？則小人遂陵，君子日消也。大壯則陽盛陰消，君子道勝。晉，以柔而進也。家人之義，惟嚴與敬。禮勝則離。家人尚嚴，其敝必乖。 注：遁而退處，必須以剛壯之道出其所處。既動而出，必須進，進而不已，人所不與，必有所傷。治家之道，失嚴正必乖。解人之難，必有所損，損而不已，必須益之。 胡。 人窮則反本，疾痛則必呼父母，故傷則反於家。 坡。 感莫如少，久莫如長，不可久而居其所者，物之變也。遁者，求遠小人而已。潔身不仕，則廢君臣之義。以天時言之，成功者退；以人道言之，大化有四。故「不可以終壯」。「明出為晉」，則晉者日也，而進者人也。「明入為夷」，則夷者日也，而傷者人也。以人屬者，迫窮禍患害相棄；以天屬者，迫窮禍患相收。故「傷於外者，必反於家」。家人之道，以嚴則不窮，以和則必乖。損而不已則虛，故必益 龔。</p><p>益而不已必決，故受之以夬。夬者，決也。決必有所遇，故受之以姤。姤者，遇也。物相遇而後聚，故受之以萃。萃者，聚也。聚而上者謂之升，故受之以升。升而不已必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。革物者莫若鼎，故受之以鼎。主器者莫若長子，故受之以震。震者，動也。物不可以終動，止之，故受之以艮。艮者，止也。物不可以終止，故受之以漸。漸者，進也。進必有所歸，故受之以「歸妹」。</p><p>益而不已則盈，故必決。以正決邪，必有所遇。井久則濁穢，宜革易其故。既已去，故宜制器立法以治新。鼎所以和齊生物，成新之器也，故取象焉。 注：君子既有所遇，則萬物莫不聚萃。萃之於上，必須升進，升而不已，其道必困。困之既久，必反於下。井道既得其所，不可不革治之。革之必得其道，有鼎新之義焉。物既鼎新，主之者莫若長子。物不可以終動，動必有所止。止物必有漸，漸必有所歸。 胡 遇者，小人不足以間君子也。傳曰：「躍於龠，合於合，登於升。」故聚而上者為升。鼎者，器也，國家之所寶，故主器者莫若長子。 龔</p><p>得其所歸者必大，故受之以豐。豐者，大也。窮大者必失其居，故受之以旅。旅而無所容，故受之以巽。巽者，入也。入而後說之，故受之以兌。兌者，說也。說而後散之，故受之以渙。渙者，離也。物不可以終離，故受之以節。節而信之，故受之以中孚。有其信者必行之，故受之以小過。有過物者必濟，故受之以既濟。物不可窮也，故受之以未濟終焉。</p><p>旅而無所容，以巽故得入。說不可偏系，故宜散。渙者，發散而無所壅滯，則殊趣各肆，不反而乖離。大事有節，則物之所同守而不散。既有節，則宜信以守之。守其信者，失貞而不諒之道，而以信為過，故曰小過也。「行過乎恭，禮過乎儉，可以矯世厲俗，有所濟也。有為而能濟者，以己窮物者也。物窮則乖，功極則亂，其可濟乎？」 注：窮大者必失其居。 龔。 周易義海撮要卷十、</p>',14)])])}const m=p(i,[["render",o]]);export{h as __pageData,m as default};
